    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
    "type": "function",
    "name": "save_derived",
    "description": "Schreibt DEINE abgeleiteten Items als offizielles derived.json. Jedes Item braucht text \u002B sourceArtifactItemIds (\u003E=1 echte itemId) \u002B optional assumptions \u002B rationale. Stabile IDs werden automatisch vergeben. Rufe es GENAU EINMAL am Ende auf.",
    "parameters": {
      "type": "object",
      "properties": {
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "text": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "sourceArtifactItemIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "assumptions": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": [
                  "string",
                  "null"
                ]
              }
            },
            "required": [
              "text",
              "sourceArtifactItemIds",
              "assumptions",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "items"
      ]
    }
